1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	    <meta charset="UTF-8">
5	    <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	    <title>Omniroute AI</title>
7	    <style>
8	        :root {
9	            --bg-primary: #0f1419;
10	            --bg-secondary: #1a1f29;
11	            --bg-tertiary: #252b36;
