17	            --success: #3fb950;
18	            --error: #f85149;
19	            --warning: #d29922;
20	        }
21	
22	        * {
23	            margin: 0;
24	            padding: 0;
25	            box-sizing: border-box;
26	        }
27	
28	        body {
29	            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Noto Sans', Helvetica, Arial, sans-serif;
30	            background: var(--bg-primary);
31	            color: var(--text-primary);
32	            line-height: 1.6;
33	            height: 100vh;
34	            overflow: hidden;
35	        }
36	
37	        .container {
38	            display: flex;
39	            height: 100vh;
40	        }
41	
42	        .sidebar {
43	            width: 280px;
44	            background: var(--bg-secondary);
45	            border-right: 1px solid var(--border-color);
46	            display: flex;
47	            flex-direction: column;
48	            padding: 16px;
49	        }
50	
51	        .logo {
52	            font-size: 24px;
53	            font-weight: 700;
54	            margin-bottom: 24px;
55	            color: var(--accent-primary);
56	        }
57	
58	        .model-selector {
59	            margin-bottom: 24px;
60	        }
61	
62	        .model-selector label {
63	            display: block;
64	            font-size: 12px;
65	            color: var(--text-secondary);
66	            margin-bottom: 8px;
67	            text-transform: uppercase;
68	            letter-spacing: 0.5px;
69	        }
70	
71	        .model-selector select {
72	            width: 100%;
73	            padding: 10px 12px;
74	            background: var(--bg-tertiary);
75	            color: var(--text-primary);
76	            border: 1px solid var(--border-color);
77	            border-radius: 6px;
78	            font-size: 14px;
79	            cursor: pointer;
80	        }
81	
82	        .combo-section {
83	            margin-bottom: 24px;
84	        }
85	
86	        .combo-section h3 {
87	            font-size: 12px;
88	            color: var(--text-secondary);
89	            margin-bottom: 12px;
90	            text-transform: uppercase;
91	            letter-spacing: 0.5px;
92	        }
93	
94	        .combo-list {
95	            display: flex;
96	            flex-direction: column;
97	            gap: 8px;
98	        }
99	
100	        .combo-btn {
101	            padding: 10px 12px;
102	            background: var(--bg-tertiary);
103	            color: var(--text-primary);
104	            border: 1px solid var(--border-color);
105	            border-radius: 6px;
106	            text-align: left;
107	            cursor: pointer;
108	            transition: all 0.2s;
109	            font-size: 14px;
110	        }
111	
112	        .combo-btn:hover {
113	            background: var(--border-color);
114	            border-color: var(--accent-primary);
115	        }
116	
117	        .combo-btn.active {
118	            background: var(--accent-primary);
119	            color: white;
120	            border-color: var(--accent-primary);
121	        }
122	
123	        .stats {
124	            margin-top: auto;
125	            padding-top: 16px;
126	            border-top: 1px solid var(--border-color);
127	        }
128	
129	        .stat-item {
130	            display: flex;
131	            justify-content: space-between;
132	            margin-bottom: 8px;
133	            font-size: 13px;
134	        }
135	
136	        .stat-label {
137	            color: var(--text-secondary);
138	        }
139	
140	        .stat-value {
141	            color: var(--text-primary);
142	            font-weight: 600;
143	        }
144	
145	        .main-content {
146	            flex: 1;
147	            display: flex;
148	            flex-direction: column;
149	        }
150	
151	        .header {
152	            padding: 16px 24px;
153	            background: var(--bg-secondary);
154	            border-bottom: 1px solid var(--border-color);
155	            display: flex;
156	            justify-content: space-between;
157	            align-items: center;
158	        }
159	
160	        .header h1 {
161	            font-size: 18px;
162	            font-weight: 600;
163	        }
164	
165	        .header-actions {
166	            display: flex;
167	            gap: 12px;
168	        }
169	
170	        .btn {
171	            padding: 8px 16px;
172	            background: var(--bg-tertiary);
173	            color: var(--text-primary);
174	            border: 1px solid var(--border-color);
175	            border-radius: 6px;
176	            cursor: pointer;
177	            font-size: 13px;
178	            transition: all 0.2s;
179	        }
180	
181	        .btn:hover {
182	            background: var(--border-color);
183	        }
184	
185	        .btn-primary {
186	            background: var(--accent-primary);
187	            border-color: var(--accent-primary);
188	        }
189	
190	        .btn-primary:hover {
191	            background: var(--accent-hover);
192	        }
193	
194	        .chat-container {
195	            flex: 1;
196	            overflow-y: auto;
197	            padding: 24px;
198	            scroll-behavior: smooth;
199	        }
200	
201	        .message {
202	            margin-bottom: 24px;
203	            display: flex;
204	            gap: 12px;
205	        }
206	
207	        .message-avatar {
208	            width: 32px;
209	            height: 32px;
210	            border-radius: 50%;
211	            display: flex;
212	            align-items: center;
213	            justify-content: center;
214	            font-weight: 600;
215	            font-size: 14px;
216	            flex-shrink: 0;
217	        }
218	
219	        .user-avatar {
220	            background: var(--accent-primary);
221	            color: white;
222	        }
223	
224	        .ai-avatar {
225	            background: var(--bg-tertiary);
226	            color: var(--accent-primary);
227	        }
228	
229	        .message-content {
230	            flex: 1;
231	        }
232	
233	        .message-header {
234	            display: flex;
235	            align-items: center;
236	            gap: 8px;
237	            margin-bottom: 6px;
238	        }
239	
240	        .message-name {
241	            font-weight: 600;
242	            font-size: 14px;
243	        }
244	
245	        .message-time {
246	            font-size: 12px;
247	            color: var(--text-secondary);
248	        }
249	
250	        .message-text {
251	            color: var(--text-primary);
252	            line-height: 1.6;
253	            white-space: pre-wrap;
254	        }
255	
256	        .message-text code {
257	            background: var(--bg-tertiary);
258	            padding: 2px 6px;
259	            border-radius: 3px;
260	            font-family: 'Consolas', 'Monaco', monospace;
261	            font-size: 13px;
262	        }
263	
264	        .message-text pre {
265	            background: var(--bg-tertiary);
266	            padding: 12px;
267	            border-radius: 6px;
268	            overflow-x: auto;
269	            margin: 8px 0;
270	        }
271	
272	        .message-attachments {
273	            margin-top: 8px;
274	            display: flex;
275	            flex-wrap: wrap;
276	            gap: 8px;
277	        }
278	
279	        .attachment-preview {
280	            position: relative;
281	            max-width: 300px;
282	            border: 1px solid var(--border-color);
283	            border-radius: 8px;
284	            overflow: hidden;
285	            background: var(--bg-tertiary);
286	        }
287	
288	        .attachment-preview img {
289	            display: block;
290	            max-width: 100%;
291	            height: auto;
292	        }
293	
294	        .attachment-file {
295	            display: flex;
296	            align-items: center;
297	            gap: 8px;
298	            padding: 8px 12px;
299	            background: var(--bg-tertiary);
300	            border: 1px solid var(--border-color);
301	            border-radius: 6px;
302	            font-size: 13px;
303	        }
304	
305	        .attachment-icon {
306	            font-size: 18px;
307	        }
308	
309	        .input-container {
310	            padding: 16px 24px;
311	            background: var(--bg-secondary);
312	            border-top: 1px solid var(--border-color);
313	        }
314	
315	        .attachments-preview {
316	            display: flex;
317	            flex-wrap: wrap;
318	            gap: 8px;
319	            margin-bottom: 12px;
320	        }
321	
322	        .attachment-item {
323	            position: relative;
324	            display: inline-block;
325	        }
326	
327	        .attachment-thumb {
328	            max-width: 80px;
329	            max-height: 80px;
330	            border-radius: 6px;
331	            border: 1px solid var(--border-color);
332	            object-fit: cover;
333	        }
334	
335	        .attachment-file-preview {
336	            display: flex;
337	            align-items: center;
338	            gap: 8px;
339	            padding: 8px 12px;
340	            background: var(--bg-tertiary);
341	            border: 1px solid var(--border-color);
342	            border-radius: 6px;
343	            font-size: 12px;
344	            max-width: 200px;
345	        }
346	
347	        .attachment-file-preview .file-name {
348	            overflow: hidden;
349	            text-overflow: ellipsis;
350	            white-space: nowrap;
351	        }
352	
353	        .remove-attachment {
354	            position: absolute;
355	            top: -6px;
356	            right: -6px;
357	            width: 20px;
358	            height: 20px;
359	            background: var(--error);
360	            color: white;
361	            border: none;
362	            border-radius: 50%;
363	            cursor: pointer;
364	            display: flex;
365	            align-items: center;
366	            justify-content: center;
367	            font-size: 12px;
368	            font-weight: bold;
369	        }
370	
371	        .input-wrapper {
372	            display: flex;
373	            gap: 12px;
374	            align-items: flex-end;
375	        }
376	
377	        .input-actions {
378	            display: flex;
379	            flex-direction: column;
380	            gap: 8px;
381	        }
382	
383	        .attach-btn {
384	            width: 40px;
385	            height: 40px;
386	            background: var(--bg-tertiary);
387	            border: 1px solid var(--border-color);
388	            border-radius: 8px;
389	            cursor: pointer;
390	            display: flex;
391	            align-items: center;
392	            justify-content: center;
393	            font-size: 18px;
394	            transition: all 0.2s;
395	        }
396	
397	        .attach-btn:hover {
398	            background: var(--border-color);
399	            border-color: var(--accent-primary);
400	        }
401	
402	        .input-box {
403	            flex: 1;
404	            background: var(--bg-tertiary);
405	            border: 1px solid var(--border-color);
406	            border-radius: 8px;
407	            padding: 12px;
408	            color: var(--text-primary);
409	            font-size: 14px;
410	            resize: none;
411	            min-height: 48px;
412	            max-height: 200px;
413	            font-family: inherit;
414	        }
415	
416	        .input-box:focus {
417	            outline: none;
418	            border-color: var(--accent-primary);
419	        }
420	
421	        .send-btn {
422	            padding: 12px 24px;
423	            background: var(--accent-primary);
424	            color: white;
425	            border: none;
426	            border-radius: 8px;
427	            cursor: pointer;
428	            font-size: 14px;
429	            font-weight: 600;
430	            transition: all 0.2s;
431	        }
432	
433	        .send-btn:hover:not(:disabled) {
434	            background: var(--accent-hover);
435	        }
436	
437	        .send-btn:disabled {
438	            opacity: 0.5;
439	            cursor: not-allowed;
440	        }
441	
442	        .loading {
443	            display: flex;
444	            gap: 4px;
445	            padding: 8px 0;
446	        }
447	
448	        .loading-dot {
449	            width: 8px;
450	            height: 8px;
451	            border-radius: 50%;
452	            background: var(--accent-primary);
453	            animation: bounce 1.4s infinite ease-in-out both;
454	        }
455	
456	        .loading-dot:nth-child(1) { animation-delay: -0.32s; }
457	        .loading-dot:nth-child(2) { animation-delay: -0.16s; }
458	
459	        @keyframes bounce {
460	            0%, 80%, 100% { transform: scale(0); }
461	            40% { transform: scale(1); }
462	        }
463	
464	        .status-indicator {
465	            display: inline-block;
466	            width: 8px;
467	            height: 8px;
468	            border-radius: 50%;
469	            margin-right: 6px;
470	        }
471	
472	        .status-online {
473	            background: var(--success);
474	            box-shadow: 0 0 8px var(--success);
475	        }
476	
477	        .status-offline {
478	            background: var(--error);
479	        }
480	
481	        .file-input {
482	            display: none;
483	        }
484	
485	        @media (max-width: 768px) {
486	            .sidebar {
487	                width: 100%;
488	                position: absolute;
489	                z-index: 100;
490	                transform: translateX(-100%);
491	                transition: transform 0.3s;
492	            }
493	
494	            .sidebar.open {
495	                transform: translateX(0);
496	            }
497	        }
498	    </style>
499	</head>
500	<body>
501	    <div class="container">
502	        <aside class="sidebar">
503	            <div class="logo">⚡ Omniroute AI</div>
504	
505	            <div class="model-selector">
506	                <label>Model</label>
507	                <select id="modelSelect">
508	                    <option value="kr/claude-sonnet-4.5">Sonnet 4.5</option>
509	                    <option value="kr/claude-sonnet-4">Sonnet 4</option>
510	                    <option value="claude-sonnet-5-5">Sonnet 5.5</option>
511	                    <option value="claude-opus-5-5">Opus 5.5</option>
512	                    <option value="claude-haiku-5-5">Haiku 5.5</option>
513	                    <option value="claude-fable-5-1">Fable 5.1</option>
514	                </select>
515	            </div>
516	
517	            <div class="combo-section">
518	                <h3>Quick Combos</h3>
519	                <div class="combo-list">
520	                    <button class="combo-btn" data-combo="my-combo">My Combo</button>
521	                    <button class="combo-btn" data-combo="code-review">Code Review</button>
522	                    <button class="combo-btn" data-combo="creative">Creative Mode</button>
523	                    <button class="combo-btn" data-combo="fast">Fast Response</button>
524	                </div>
525	            </div>
526	
527	            <div class="stats">
528	                <div class="stat-item">
529	                    <span class="stat-label">Status</span>
530	                    <span class="stat-value">
531	                        <span class="status-indicator status-online"></span>
532	                        Online
533	                    </span>
534	                </div>
535	                <div class="stat-item">
536	                    <span class="stat-label">Tokens Used</span>
537	                    <span class="stat-value" id="tokensUsed">0</span>
538	                </div>
539	                <div class="stat-item">
540	                    <span class="stat-label">Messages</span>
541	                    <span class="stat-value" id="messageCount">0</span>
542	                </div>
543	            </div>
544	        </aside>
545	
546	        <main class="main-content">
547	            <header class="header">
548	                <h1>Omniroute AI</h1>
549	                <div class="header-actions">
550	                    <button class="btn" onclick="clearChat()">Clear Chat</button>
551	                    <button class="btn" onclick="exportChat()">Export</button>
552	                    <button class="btn btn-primary" onclick="openSettings()">Settings</button>
553	                </div>
554	            </header>
555	
556	            <div class="chat-container" id="chatContainer">
557	                <div class="message">
558	                    <div class="message-avatar ai-avatar">AI</div>
559	                    <div class="message-content">
560	                        <div class="message-header">
561	                            <span class="message-name">Omniroute AI</span>
562	                            <span class="message-time">Just now</span>
563	                        </div>
564	                        <div class="message-text">Hey! I'm Omniroute AI, your intelligent assistant. I can help you with coding, analysis, creative tasks, and more. You can also attach images and files to your messages. What would you like to work on today?</div>
565	                    </div>
566	                </div>
567	            </div>
568	
569	            <div class="input-container">
570	                <div class="attachments-preview" id="attachmentsPreview"></div>
571	                <div class="input-wrapper">
572	                    <div class="input-actions">
573	                        <button class="attach-btn" onclick="document.getElementById('fileInput').click()" title="Attach files">
574	                            📎
575	                        </button>
576	                    </div>
577	                    <textarea
578	                        id="messageInput"
579	                        class="input-box"
580	                        placeholder="Type your message... (Shift+Enter for new line)"
581	                        rows="1"
582	                    ></textarea>
583	                    <button class="send-btn" id="sendBtn" onclick="sendMessage()">Send</button>
584	                </div>
585	                <input type="file" id="fileInput" class="file-input" multiple accept="image/*,.pdf,.doc,.docx,.txt,.json,.csv,.xlsx" onchange="handleFileSelect(event)">
586	            </div>
587	        </main>
588	    </div>
589	
590	    <script>
591	        let messageCount = 0;
592	        let totalTokens = 0;
593	        let currentModel = 'kr/claude-sonnet-4.5';
594	        let isLoading = false;
595	        let attachedFiles = [];
596	
597	        // Initialize
598	        document.addEventListener('DOMContentLoaded', () => {
599	            const input = document.getElementById('messageInput');
600	
601	            // Auto-resize textarea
602	            input.addEventListener('input', () => {
603	                input.style.height = 'auto';
604	                input.style.height = input.scrollHeight + 'px';
605	            });
606	
607	            // Enter to send, Shift+Enter for new line
608	            input.addEventListener('keydown', (e) => {
609	                if (e.key === 'Enter' && !e.shiftKey) {
610	                    e.preventDefault();
611	                    sendMessage();
612	                }
613	            });
614	
615	            // Model selection
616	            document.getElementById('modelSelect').addEventListener('change', (e) => {
617	                currentModel = e.target.value;
618	                console.log('Model changed to:', currentModel);
619	            });
620	
621	            // Combo buttons
622	            document.querySelectorAll('.combo-btn').forEach(btn => {
623	                btn.addEventListener('click', () => {
624	                    document.querySelectorAll('.combo-btn').forEach(b => b.classList.remove('active'));
625	                    btn.classList.add('active');
626	                    const combo = btn.dataset.combo;
627	                    applyCombo(combo);
628	                });
629	            });
630	
631	            // Drag and drop support
632	            const container = document.getElementById('chatContainer');
633	            container.addEventListener('dragover', (e) => {
634	                e.preventDefault();
635	                container.style.background = 'rgba(88, 166, 255, 0.1)';
636	            });
637	
638	            container.addEventListener('dragleave', (e) => {
639	                container.style.background = '';
640	            });
641	
642	            container.addEventListener('drop', (e) => {
643	                e.preventDefault();
644	                container.style.background = '';
645	                const files = Array.from(e.dataTransfer.files);
646	                handleFiles(files);
647	            });
648	        });
649	
650	        function handleFileSelect(event) {
651	            const files = Array.from(event.target.files);
652	            handleFiles(files);
653	            event.target.value = ''; // Reset input
654	        }
655	
656	        function handleFiles(files) {
657	            files.forEach(file => {
658	                if (file.size > 10 * 1024 * 1024) { // 10MB limit
659	                    alert(`File ${file.name} is too large. Maximum size is 10MB.`);
660	                    return;
661	                }
662	
663	                const fileData = {
664	                    file: file,
665	                    name: file.name,
666	                    type: file.type,
667	                    size: file.size
668	                };
669	
670	                attachedFiles.push(fileData);
671	
672	                // Read file for preview
673	                const reader = new FileReader();
674	                reader.onload = (e) => {
675	                    fileData.data = e.target.result;
676	                    renderAttachmentPreviews();
677	                };
678	
679	                if (file.type.startsWith('image/')) {
680	                    reader.readAsDataURL(file);
681	                } else {
682	                    reader.readAsDataURL(file);
683	                }
684	            });
685	        }
686	
687	        function renderAttachmentPreviews() {
688	            const preview = document.getElementById('attachmentsPreview');
689	            preview.innerHTML = '';
690	
691	            attachedFiles.forEach((fileData, index) => {
692	                const item = document.createElement('div');
693	                item.className = 'attachment-item';
694	
695	                if (fileData.type.startsWith('image/')) {
696	                    const img = document.createElement('img');
697	                    img.src = fileData.data;
698	                    img.className = 'attachment-thumb';
699	                    item.appendChild(img);
700	                } else {
701	                    const filePreview = document.createElement('div');
702	                    filePreview.className = 'attachment-file-preview';
703	                    filePreview.innerHTML = `
704	                        <span class="attachment-icon">📄</span>
705	                        <span class="file-name">${fileData.name}</span>
706	                    `;
707	                    item.appendChild(filePreview);
708	                }
709	
710	                const removeBtn = document.createElement('button');
711	                removeBtn.className = 'remove-attachment';
712	                removeBtn.innerHTML = '×';
713	                removeBtn.onclick = () => removeAttachment(index);
714	                item.appendChild(removeBtn);
715	
716	                preview.appendChild(item);
717	            });
718	        }
719	
720	        function removeAttachment(index) {
721	            attachedFiles.splice(index, 1);
722	            renderAttachmentPreviews();
723	        }
724	
725	        function applyCombo(combo) {
726	            console.log('Applying combo:', combo);
727	
728	            const comboConfigs = {
729	                'my-combo': {
730	                    model: 'kr/claude-sonnet-4.5',
731	                    systemPrompt: 'You are Omniroute AI, an intelligent assistant optimized for development tasks.'
732	                },
733	                'code-review': {
734	                    model: 'claude-opus-5-5',
735	                    systemPrompt: 'You are Omniroute AI in code review mode. Focus on finding bugs, security issues, and suggesting improvements.'
736	                },
737	                'creative': {
738	                    model: 'claude-sonnet-5-5',
739	                    systemPrompt: 'You are Omniroute AI in creative mode. Think outside the box and provide innovative solutions.'
740	                },
