1	import { useEffect, useReducer, useState } from "react";
2	import { playBeep } from "./audio/beep";
3	import OfficeCanvas from "./scene/OfficeCanvas";
4	import { loadState, saveState } from "./state/persistence";
5	import { reduce } from "./state/reducer";
6	import { EMPLOYEE_IDS } from "./state/types";
7	import type { Action, ActionBody, EmployeeId } from "./state/types";
8	import ActivityLog from "./ui/ActivityLog";
9	import CharacterPanel from "./ui/CharacterPanel";
10	import EmployeeList from "./ui/EmployeeList";
11	import TaskBoard from "./ui/TaskBoard";
12	import Toolbar from "./ui/Toolbar";
13	
14	const SETTLE_MS = 3000;
15	const REJECTABLE = new Set(["createTask", "assignTask", "startTask", "completeTask", "setState"]);
16	
17	export default function App() {
18	  const [state, dispatch] = useReducer(reduce, undefined, loadState);
19	  const [selectedId, setSelectedId] = useState<EmployeeId | null>(null);
20	  const [paused, setPaused] = useState(false);
21	  const [boardOpen, setBoardOpen] = useState(false);
22	
23	  useEffect(() => saveState(state), [state]);
24	  useEffect(() => {
25	    document.documentElement.dataset.theme = state.settings.theme;
26	  }, [state.settings.theme]);
27	
28	  const completed = EMPLOYEE_IDS.filter((id) => state.employees[id].state === "completed").join();
29	  useEffect(() => {
30	    const timers = completed
31	      ? completed.split(",").map((id) =>
32	          setTimeout(() => dispatch({ type: "settleCompleted", employeeId: id as EmployeeId, at: Date.now() }), SETTLE_MS),
33	        )
34	      : [];
35	    return () => timers.forEach(clearTimeout);
36	  }, [completed]);
37	
38	  const act = (body: ActionBody) => {
39	    const action = { ...body, at: Date.now() } as Action;
40	    if (state.settings.sound) {
41	      const next = reduce(state, action);
42	      if (REJECTABLE.has(action.type) && next.error) playBeep("error");
43	      else if (action.type === "assignTask" || (action.type === "createTask" && action.assigneeId)) playBeep("assign");
44	      else if (action.type === "startTask") playBeep("start");
45	      else if (action.type === "completeTask") playBeep("complete");
46	      else if (action.type === "setState" && action.state === "error") playBeep("error");
47	    }
48	    dispatch(action);
49	  };
50	
51	  const employees = EMPLOYEE_IDS.map((id) => state.employees[id]);
52	  const selected = selectedId ? state.employees[selectedId] : null;
53	
54	  return (
55	    <div className="app">
56	      <Toolbar
57	        paused={paused}
58	        onTogglePause={() => setPaused((p) => !p)}
59	        settings={state.settings}
60	        act={act}
61	        boardOpen={boardOpen}
62	        onToggleBoard={() => setBoardOpen((o) => !o)}
63	      />
64	      {state.error && (
65	        <div className="banner" role="alert">
66	          {state.error} <button onClick={() => act({ type: "dismissError" })}>Dismiss</button>
67	        </div>
68	      )}
69	      <div className="main">
70	        <OfficeCanvas state={state} selectedId={selectedId} paused={paused} onSelect={setSelectedId} />
71	        <aside className="side">
72	          <EmployeeList employees={employees} selectedId={selectedId} onSelect={setSelectedId} />
73	          {selected && (
74	            <CharacterPanel
75	              key={selected.id}
76	              employee={selected}
77	              tasks={state.tasks}
78	              act={act}
79	              onClose={() => setSelectedId(null)}
80	              onOpenBoard={() => setBoardOpen(true)}
81	            />
82	          )}
83	          <ActivityLog log={state.log} act={act} />
84	        </aside>
85	      </div>
86	      {boardOpen && <TaskBoard tasks={state.tasks} employees={employees} act={act} onClose={() => setBoardOpen(false)} />}
87	    </div>
88	  );
89	}
