1	import { EMPLOYEE_IDS } from "./types";
2	import type { Action, Employee, EmployeeId, OfficeState, Task } from "./types";
3	
4	const LOG_CAP = 50;
5	const ACTIVITY_CAP = 20;
6	
7	export const ROLES: Record<EmployeeId, string> = {
8	  planner: "Planner / Architect",
9	  developer: "Developer",
10	  qa: "QA / Debugger",
11	  security: "Security Auditor",
12	  researcher: "Researcher / Codebase Explorer",
13	};
14	
15	export function initialEmployees(): Record<EmployeeId, Employee> {
16	  const out = {} as Record<EmployeeId, Employee>;
17	  for (const id of EMPLOYEE_IDS) {
18	    out[id] = { id, role: ROLES[id], state: "idle", currentTaskId: null, activity: [] };
19	  }
20	  return out;
21	}
22	
23	export function initialState(): OfficeState {
24	  return {
25	    employees: initialEmployees(),
26	    tasks: [],
27	    log: [],
28	    settings: { theme: "day", sound: false },
29	    error: null,
30	  };
31	}
32	
33	const reject = (s: OfficeState, message: string): OfficeState => ({ ...s, error: message });
34	
35	function logged(s: OfficeState, at: number, employeeId: EmployeeId | null, text: string): OfficeState {
36	  const entry = { at, employeeId, text };
37	  const employees = employeeId
38	    ? {
39	        ...s.employees,
40	        [employeeId]: {
41	          ...s.employees[employeeId],
42	          activity: [...s.employees[employeeId].activity, entry].slice(-ACTIVITY_CAP),
43	        },
44	      }
45	    : s.employees;
46	  return { ...s, employees, log: [...s.log, entry].slice(-LOG_CAP), error: null };
47	}
48	
49	const patchTask = (s: OfficeState, id: string, patch: Partial<Task>): OfficeState => ({
50	  ...s,
51	  tasks: s.tasks.map((t) => (t.id === id ? { ...t, ...patch } : t)),
52	});
53	
54	const patchEmployee = (s: OfficeState, id: EmployeeId, patch: Partial<Employee>): OfficeState => ({
55	  ...s,
56	  employees: { ...s.employees, [id]: { ...s.employees[id], ...patch } },
57	});
58	
59	export function reduce(s: OfficeState, a: Action): OfficeState {
60	  switch (a.type) {
61	    case "createTask": {
62	      const title = a.title.trim();
63	      if (!title) return reject(s, "Task title is empty.");
64	      const task: Task = {
65	        id: a.id,
66	        title,
67	        assigneeId: a.assigneeId ?? null,
68	        status: "todo",
69	        createdAt: a.at,
70	        updatedAt: a.at,
71	      };
72	      return logged({ ...s, tasks: [...s.tasks, task] }, a.at, task.assigneeId, `Task created: ${title}`);
73	    }
74	    case "assignTask": {
75	      const task = s.tasks.find((t) => t.id === a.taskId);
76	      if (!task) return reject(s, "Task not found.");
77	      if (task.status !== "todo") return reject(s, "Only to-do tasks can be assigned.");
78	      return logged(
79	        patchTask(s, task.id, { assigneeId: a.assigneeId, updatedAt: a.at }),
80	        a.at,
81	        a.assigneeId,
82	        `Assigned: ${task.title}`,
83	      );
84	    }
85	    case "startTask": {
86	      const task = s.tasks.find((t) => t.id === a.taskId);
87	      if (!task) return reject(s, "Task not found.");
88	      if (task.status !== "todo") return reject(s, "Task was already started or finished.");
89	      if (!task.assigneeId) return reject(s, "Assign the task to someone first.");
90	      const emp = s.employees[task.assigneeId];
91	      if (emp.currentTaskId !== null) return reject(s, `${emp.role} is busy with another task.`);
92	      const next = patchEmployee(patchTask(s, task.id, { status: "active", updatedAt: a.at }), emp.id, {
93	        state: "working",
94	        currentTaskId: task.id,
95	      });
96	      return logged(next, a.at, emp.id, `Started: ${task.title}`);
97	    }
98	    case "completeTask": {
99	      const task = s.tasks.find((t) => t.id === a.taskId);
100	      if (!task) return reject(s, "Task not found.");
101	      if (task.status !== "active" || !task.assigneeId) return reject(s, "Only active tasks can be completed.");
102	      const next = patchEmployee(patchTask(s, task.id, { status: "done", updatedAt: a.at }), task.assigneeId, {
103	        state: "completed",
104	        currentTaskId: null,
105	      });
106	      return logged(next, a.at, task.assigneeId, `Completed: ${task.title}`);
107	    }
108	    case "setState": {
109	      const emp = s.employees[a.employeeId];
110	      if (a.state === "working" && !emp.currentTaskId) return reject(s, "Start a task to make someone work.");
111	      return logged(patchEmployee(s, emp.id, { state: a.state }), a.at, emp.id, `State set to ${a.state}`);
112	    }
113	    case "settleCompleted": {
114	      if (s.employees[a.employeeId].state !== "completed") return s;
115	      return patchEmployee(s, a.employeeId, { state: "idle" });
116	    }
117	    case "setTheme":
118	      return { ...s, settings: { ...s.settings, theme: a.theme } };
119	    case "setSound":
120	      return { ...s, settings: { ...s.settings, sound: a.sound } };
121	    case "clearLog":
122	      return { ...s, log: [] };
123	    case "dismissError":
124	      return { ...s, error: null };
125	  }
126	}
