18	  typeof v.createdAt === "number" && typeof v.updatedAt === "number" &&
19	  (v.status === "todo" || v.status === "active" || v.status === "done") &&
20	  (v.assigneeId === null || (EMPLOYEE_IDS as readonly unknown[]).includes(v.assigneeId));
21	
22	export function saveState(state: OfficeState, storage: Pick<Storage, "setItem"> = globalThis.localStorage): void {
23	  try {
24	    const employees = Object.fromEntries(
25	      EMPLOYEE_IDS.map((id) => {
26	        const { state: st, currentTaskId, activity } = state.employees[id];
27	        return [id, { state: st, currentTaskId, activity }];
28	      }),
29	    );
30	    storage.setItem(
31	      STORAGE_KEY,
32	      JSON.stringify({ version: VERSION, tasks: state.tasks, employees, log: state.log, settings: state.settings }),
33	    );
34	  } catch {
35	    // storage unavailable or full: the app keeps running without persistence
36	  }
37	}
38	
39	export function loadState(storage: Pick<Storage, "getItem"> = globalThis.localStorage): OfficeState {
40	  const base = initialState();
41	  try {
42	    const raw = storage.getItem(STORAGE_KEY);
43	    if (!raw) return base;
44	    const data: unknown = JSON.parse(raw);
45	    if (!isRec(data) || data.version !== VERSION) return base;
46	
47	    const tasks = Array.isArray(data.tasks) ? data.tasks.filter(isTask) : [];
48	    const log = Array.isArray(data.log) ? data.log.filter(isEntry).slice(-50) : [];
49	    const savedEmps = isRec(data.employees) ? data.employees : {};
50	    for (const id of EMPLOYEE_IDS) {
51	      const e = savedEmps[id];
52	      if (!isRec(e)) continue;
53	      const taskId = typeof e.currentTaskId === "string" ? e.currentTaskId : null;
54	      let state = STATES.includes(e.state as EmployeeState) ? (e.state as EmployeeState) : "idle";
55	      let currentTaskId = taskId;
56	      const active = tasks.some((t) => t.id === taskId && t.status === "active");
57	      if (state === "completed") state = "idle";
58	      if (state === "working" && !active) state = "idle";
59	      if (!active) currentTaskId = null;
60	      base.employees[id] = {
61	        ...base.employees[id],
62	        state,
63	        currentTaskId,
64	        activity: Array.isArray(e.activity) ? e.activity.filter(isEntry).slice(-20) : [],
65	      };
66	    }
67	    const s = isRec(data.settings) ? data.settings : {};
68	    base.settings = {
69	      theme: s.theme === "night" ? "night" : "day",
70	      sound: s.sound === true,
71	    };
72	    return { ...base, tasks, log };
73	  } catch {
74	    return initialState();
75	  }
76	}
