1	import { useEffect, useRef, useState } from "react";
2	import type { ActionBody, Employee, EmployeeState, Task } from "../state/types";
3	import { DEMO_TEXT, cap, clock } from "./format";
4	
5	const STATES: EmployeeState[] = ["idle", "working", "thinking", "waiting", "completed", "error"];
6	
7	interface Props {
8	  employee: Employee;
9	  tasks: Task[];
10	  act: (a: ActionBody) => void;
11	  onClose: () => void;
12	  onOpenBoard: () => void;
13	}
14	
15	export default function CharacterPanel({ employee, tasks, act, onClose, onOpenBoard }: Props) {
16	  const ref = useRef<HTMLElement>(null);
17	  const [pick, setPick] = useState("");
18	
19	  useEffect(() => {
20	    const prev = document.activeElement as HTMLElement | null;
21	    ref.current?.focus();
22	    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onClose();
23	    document.addEventListener("keydown", onKey);
24	    return () => {
25	      document.removeEventListener("keydown", onKey);
26	      prev?.focus?.();
27	    };
28	  }, []);
29	
30	  const active = tasks.find((t) => t.id === employee.currentTaskId);
31	  const queue = tasks.filter((t) => t.assigneeId === employee.id && t.status === "todo");
32	  const assignable = tasks.filter((t) => t.status === "todo" && t.assigneeId !== employee.id);
33	  const busy = employee.currentTaskId !== null;
34	
35	  return (
36	    <section
37	      className="panel"
38	      ref={ref}
39	      tabIndex={-1}
40	      aria-label={`${employee.role} details`}
41	    >
42	      <header>
43	        <h2>{employee.role}</h2>
44	        <button onClick={onClose} aria-label="Close panel">×</button>
45	      </header>
46	      <p className="badge">{DEMO_TEXT}</p>
47	      <p>
48	        State: <span className={`chip st-${employee.state}`}>{cap(employee.state)}</span>
49	      </p>
50	      <label>
51	        Set state{" "}
52	        <select
53	          value={employee.state}
54	          onChange={(e) => act({ type: "setState", employeeId: employee.id, state: e.target.value as EmployeeState })}
55	        >
56	          {STATES.map((s) => (
57	            <option key={s} value={s}>{cap(s)}</option>
58	          ))}
59	        </select>
60	      </label>
61	
62	      <h3>Current task</h3>
63	      {active ? (
64	        <p>
65	          {active.title}{" "}
66	          <button onClick={() => act({ type: "completeTask", taskId: active.id })}>Complete</button>
67	        </p>
68	      ) : (
69	        <p className="muted">None</p>
70	      )}
71	
72	      {queue.length > 0 && (
73	        <>
74	          <h3>Queue</h3>
75	          <ul className="rows">
76	            {queue.map((t) => (
77	              <li key={t.id}>
78	                {t.title}{" "}
79	                <button disabled={busy} onClick={() => act({ type: "startTask", taskId: t.id })}>Start</button>
80	              </li>
81	            ))}
82	          </ul>
83	        </>
84	      )}
85	
86	      <h3>Assign a task</h3>
87	      {assignable.length === 0 ? (
88	        <p className="muted">
89	          No to-do tasks to assign. <button onClick={onOpenBoard}>Open task board</button>
90	        </p>
91	      ) : (
92	        <div className="row">
93	          <select value={pick} onChange={(e) => setPick(e.target.value)} aria-label="Task to assign">
94	            <option value="">Choose a task…</option>
95	            {assignable.map((t) => (
96	              <option key={t.id} value={t.id}>{t.title}</option>
97	            ))}
98	          </select>
99	          <button
100	            disabled={!pick}
101	            onClick={() => {
102	              act({ type: "assignTask", taskId: pick, assigneeId: employee.id });
103	              setPick("");
104	            }}
105	          >
106	            Assign
107	          </button>
108	        </div>
109	      )}
110	
111	      <h3>Recent activity</h3>
112	      {employee.activity.length === 0 ? (
113	        <p className="muted">Nothing yet.</p>
114	      ) : (
115	        <ul className="rows log">
116	          {[...employee.activity].reverse().map((a, i) => (
117	            <li key={i}>
118	              <span className="muted">{clock(a.at)}</span> {a.text}
119	            </li>
120	          ))}
121	        </ul>
122	      )}
123	    </section>
124	  );
125	}
