1	import type { EmployeeId, EmployeeState } from "../state/types";
2	import { TILE } from "./layout";
3	import type { SceneObject } from "./layout";
4	
5	export type Ctx = CanvasRenderingContext2D;
6	
7	export const C = {
8	  ink: "#3b2c22",
9	  wood: "#b9824f",
10	  woodDark: "#8a5a34",
11	  woodLight: "#d5a273",
12	  cream: "#f4ead2",
13	  creamDark: "#e2d3ae",
14	  green: "#6f9a6b",
15	  greenDark: "#4d7550",
16	  blue: "#9cc3dc",
17	  blueDark: "#6f9bb8",
18	  wallA: "#b7cdb0",
19	  wallB: "#9fb897",
20	  floorA: "#eadcbd",
21	  floorB: "#e0d0ac",
22	  metal: "#7c8794",
23	  metalDark: "#566170",
24	  screen: "#7fd0e8",
25	  red: "#d9534f",
26	  yellow: "#f0c850",
27	  pot: "#b4684a",
28	};
29	
30	export const px = (ctx: Ctx, color: string, x: number, y: number, w = 1, h = 1) => {
31	  ctx.fillStyle = color;
32	  ctx.fillRect(x, y, w, h);
33	};
34	
35	type Accessory = "glasses" | "headphones" | "cap" | "badge" | "bun";
36	interface Look { hair: string; skin: string; outfit: string; outfitDark: string; accessory: Accessory }
37	
38	export const CHARACTER_LOOKS: Record<EmployeeId, Look> = {
39	  planner: { hair: "#6b3f2a", skin: "#f1c9a5", outfit: "#6f9a6b", outfitDark: "#4d7550", accessory: "glasses" },
40	  developer: { hair: "#2f2a3a", skin: "#e0ac86", outfit: "#6f9bb8", outfitDark: "#4f7894", accessory: "headphones" },
41	  qa: { hair: "#c4562d", skin: "#f6d6b8", outfit: "#e0b04a", outfitDark: "#b88a2e", accessory: "cap" },
42	  security: { hair: "#1f1f24", skin: "#b9805c", outfit: "#4a5568", outfitDark: "#2f3846", accessory: "badge" },
43	  researcher: { hair: "#e8d9a0", skin: "#f1c9a5", outfit: "#b9825f", outfitDark: "#8a5a34", accessory: "bun" },
44	};
45	
46	/** Draws a 12x14 seated character with its top-left at (x, y). `frame` drives the per-state animation. */
47	export function drawCharacter(ctx: Ctx, id: EmployeeId, x: number, y: number, state: EmployeeState, frame: number) {
48	  const L = CHARACTER_LOOKS[id];
49	  const odd = frame % 2 === 1;
50	  const bob = state === "idle" && frame % 4 >= 2 ? 1 : 0;
51	  const shake = state === "error" && odd ? 1 : 0;
52	  const ox = x + shake;
53	  const oy = y + bob;
54	
55	  px(ctx, C.ink, ox + 3, oy + 12, 6, 2); // legs/shadow
56	  px(ctx, L.outfitDark, ox + 4, oy + 12, 4, 1);
57	  px(ctx, L.outfit, ox + 2, oy + 7, 8, 5); // torso
58	  px(ctx, L.outfitDark, ox + 2, oy + 11, 8, 1);
59	
60	  // arms: typing alternates height, completed raises both hands, others rest
61	  const raised = state === "completed";
62	  const typing = state === "working";
63	  const lh = raised ? 3 : typing && odd ? 2 : 4;
64	  const rh = raised ? 3 : typing && !odd ? 2 : 4;
65	  px(ctx, L.outfit, ox, oy + 7 + lh - 1 - (raised ? 3 : 0), 2, 5 - lh + 1);
66	  px(ctx, L.outfit, ox + 10, oy + 7 + rh - 1 - (raised ? 3 : 0), 2, 5 - rh + 1);
67	  px(ctx, L.skin, ox, oy + (raised ? 5 : 11 - (typing && odd ? 1 : 0)), 2, 1);
68	  px(ctx, L.skin, ox + 10, oy + (raised ? 5 : 11 - (typing && !odd ? 1 : 0)), 2, 1);
69	
70	  px(ctx, L.skin, ox + 3, oy + 2, 6, 5); // head
71	  px(ctx, L.hair, ox + 2, oy, 8, 3);
72	  px(ctx, L.hair, ox + 2, oy + 3, 1, 3);
73	  px(ctx, L.hair, ox + 9, oy + 3, 1, 3);
74	  const blink = state === "idle" && frame % 8 === 7;
75	  px(ctx, C.ink, ox + 4, oy + (blink ? 5 : 4), 1, blink ? 1 : 2);
76	  px(ctx, C.ink, ox + 7, oy + (blink ? 5 : 4), 1, blink ? 1 : 2);
77	  if (state === "error") px(ctx, C.red, ox + 5, oy + 6, 2, 1); // grimace
78	
79	  switch (L.accessory) {
80	    case "glasses":
81	      px(ctx, C.ink, ox + 3, oy + 3, 3, 1);
82	      px(ctx, C.ink, ox + 6, oy + 3, 3, 1);
83	      break;
84	    case "headphones":
85	      px(ctx, C.ink, ox + 2, oy + 1, 8, 1);
86	      px(ctx, C.ink, ox + 1, oy + 3, 2, 3);
87	      px(ctx, C.ink, ox + 9, oy + 3, 2, 3);
88	      break;
89	    case "cap":
90	      px(ctx, C.red, ox + 2, oy, 8, 2);
91	      px(ctx, C.red, ox + 1, oy + 2, 4, 1);
92	      break;
93	    case "badge":
94	      px(ctx, C.yellow, ox + 7, oy + 8, 2, 2);
95	      break;
96	    case "bun":
97	      px(ctx, L.hair, ox + 4, oy - 2, 4, 2);
98	      break;
99	  }
100	}
101	
102	/** Small speech bubble above a character, centred on cx. State icon is pixel-drawn. */
103	export function drawMarker(ctx: Ctx, state: EmployeeState, cx: number, bottom: number, frame: number) {
104	  if (state === "idle") return;
105	  const bx = cx - 4;
106	  const by = bottom - 9;
107	  px(ctx, C.ink, bx, by, 9, 9);
108	  px(ctx, state === "error" ? C.red : C.cream, bx + 1, by + 1, 7, 7);
109	  switch (state) {
110	    case "working":
111	      px(ctx, C.blueDark, bx + 2, by + 3, 5, 3);
112	      px(ctx, C.cream, bx + 2 + (frame % 3) * 2, by + 4, 1, 1);
113	      break;
114	    case "thinking":
115	      for (let i = 0; i <= frame % 3; i++) px(ctx, C.ink, bx + 2 + i * 2, by + 4);
116	      break;
117	    case "waiting":
118	      px(ctx, C.ink, bx + 2, by + 2, 5, 5);
119	      px(ctx, C.cream, bx + 3, by + 3, 3, 3);
120	      px(ctx, C.ink, bx + 4, by + 3, 1, 2);
121	      px(ctx, C.ink, bx + 5, by + 4, 1, 1);
122	      break;
123	    case "completed":
124	      for (const [dx, dy] of [[2, 4], [3, 5], [4, 4], [5, 3], [6, 2]]) px(ctx, C.greenDark, bx + dx, by + dy);
125	      break;
126	    case "error":
127	      px(ctx, C.cream, bx + 4, by + 2, 1, 3);
128	      px(ctx, C.cream, bx + 4, by + 6);
129	      break;
130	  }
131	}
132	
133	const LAYER: Record<SceneObject["kind"], number> = {
134	  rug: 0, window: 1, bookshelf: 1, whiteboard: 1, taskBoard: 1,
135	  desk: 2, meetingTable: 2, serverRack: 2, network: 2, plant: 2, computer: 3, chair: 4,
136	};
137	export const layerOf = (o: SceneObject) => LAYER[o.kind];
138	
139	export function drawObject(ctx: Ctx, o: SceneObject, frame: number) {
140	  const x = o.x * TILE;
141	  const y = o.y * TILE;
142	  const w = o.w * TILE;
143	  const h = o.h * TILE;
144	  switch (o.kind) {
145	    case "rug":
146	      px(ctx, C.greenDark, x, y, w, h);
147	      px(ctx, C.green, x + 2, y + 2, w - 4, h - 4);
148	      px(ctx, C.cream, x + 5, y + 5, w - 10, 1);
149	      px(ctx, C.cream, x + 5, y + h - 6, w - 10, 1);
150	      break;
151	    case "window":
152	      px(ctx, C.woodDark, x, y + 1, w, h - 1);
153	      px(ctx, C.blue, x + 2, y + 3, w - 4, h - 7);
154	      px(ctx, C.woodDark, x + w / 2 - 1, y + 3, 2, h - 7);
155	      px(ctx, "#ffffff", x + 3, y + 4, 3, 1);
156	      px(ctx, C.woodLight, x - 1, y + h - 3, w + 2, 3);
157	      break;
158	    case "bookshelf": {
159	      px(ctx, C.woodDark, x, y, w, h);
160	      const books = [C.red, C.blueDark, C.green, C.yellow, C.cream];
161	      for (let row = 0; row < 3; row++) {
162	        const sy = y + 2 + row * 10;
163	        px(ctx, C.wood, x + 2, sy, w - 4, 8);
164	        for (let i = 0; i < Math.floor((w - 4) / 3); i++) {
165	          const bh = 5 + ((i + row) % 3);
166	          px(ctx, books[(i + row) % books.length], x + 2 + i * 3, sy + 8 - bh, 2, bh);
167	        }
168	      }
169	      break;
170	    }
171	    case "whiteboard":
172	      px(ctx, C.metal, x, y + 2, w, h - 4);
173	      px(ctx, "#fbf8ee", x + 2, y + 4, w - 4, h - 8);
174	      px(ctx, C.blueDark, x + 6, y + 8, 22, 1);
175	      px(ctx, C.red, x + 6, y + 12, 14, 1);
176	      px(ctx, C.green, x + 6, y + 16, 26, 1);
177	      px(ctx, C.yellow, x + w - 14, y + 7, 7, 6);
178	      break;
179	    case "taskBoard":
180	      px(ctx, C.woodDark, x, y + 2, w, h - 4);
181	      px(ctx, "#c79a63", x + 2, y + 4, w - 4, h - 8);
182	      px(ctx, C.yellow, x + 4, y + 7, 7, 6);
183	      px(ctx, "#f2a7b6", x + 14, y + 8, 7, 6);
184	      px(ctx, C.blue, x + 5, y + 16, 7, 6);
185	      px(ctx, C.green, x + 16, y + 17, 7, 6);
186	      break;
187	    case "desk":
188	      px(ctx, C.woodDark, x, y + h - 5, w, 5);
189	      px(ctx, C.wood, x, y, w, h - 5);
190	      px(ctx, C.woodLight, x, y, w, 2);
191	      px(ctx, C.cream, x + 4, y + 18, 6, 4);
192	      px(ctx, C.red, x + w - 10, y + 17, 4, 4);
193	      break;
194	    case "computer":
195	      px(ctx, C.metalDark, x + 2, y + 1, 12, 9);
196	      px(ctx, C.screen, x + 3, y + 2, 10, 6);
197	      px(ctx, "#ffffff", x + 4, y + 3 + (frame % 3) * 2, 6, 1);
198	      px(ctx, C.metal, x + 6, y + 10, 4, 2);
199	      px(ctx, C.creamDark, x + 3, y + 13, 10, 2);
200	      break;
201	    case "chair":
202	      px(ctx, C.metalDark, x + 3, y + 3, 10, 3);
203	      px(ctx, C.blueDark, x + 3, y + 6, 10, 7);
204	      px(ctx, C.metal, x + 5, y + 13, 6, 2);
205	      break;
206	    case "meetingTable":
207	      px(ctx, C.woodDark, x, y + h - 5, w, 5);
208	      px(ctx, C.wood, x, y, w, h - 5);
209	      px(ctx, C.woodLight, x, y, w, 2);
210	      px(ctx, C.metal, x + 8, y + 12, 12, 8);
211	      px(ctx, C.cream, x + 30, y + 14, 8, 6);
212	      px(ctx, C.red, x + 46, y + 16, 4, 4);
213	      break;
214	    case "serverRack": {
215	      px(ctx, C.metalDark, x, y, w, h);
216	      for (let k = 0; k < 5; k++) {
217	        px(ctx, C.metal, x + 2, y + 3 + k * 9, w - 4, 7);
218	        px(ctx, (frame + k) % 3 === 0 ? C.yellow : "#6fd08c", x + w - 7, y + 5 + k * 9, 2, 2);
219	      }
220	      break;
221	    }
222	    case "network":
223	      px(ctx, C.metalDark, x, y + 4, w, 10);
224	      for (let i = 0; i < 6; i++) px(ctx, "#222831", x + 3 + i * 4, y + 7, 3, 3);
225	      px(ctx, (frame % 2) ? "#6fd08c" : C.yellow, x + w - 5, y + 11, 2, 2);
226	      break;
227	    case "plant":
228	      px(ctx, C.pot, x + 4, y + 10, 8, 5);
229	      px(ctx, C.greenDark, x + 3, y + 3, 10, 8);
230	      px(ctx, C.green, x + 5, y + 1, 6, 8);
231	      px(ctx, C.green, x + 2, y + 6, 4, 3);
232	      break;
233	  }
234	}
