import { ROLES } from "../state/reducer";
import { AGENT_MAPPINGS } from "../state/types";
import type { ActionBody, LogEntry } from "../state/types";
import { clock } from "./format";

interface Props {
  log: LogEntry[];
  act: (a: ActionBody) => void;
}

export default function ActivityLog({ log, act }: Props) {
  return (
    <section className="activity" aria-label="Activity log">
      <header>
        <h2>Activity log</h2>
        <button disabled={log.length === 0} onClick={() => act({ type: "clearLog" })}>Clear</button>
      </header>
      {log.length === 0 ? (
        <p className="muted">Nothing yet.</p>
      ) : (
        <ul className="rows log">
          {[...log].reverse().map((l, i) => {
            const agent = l.employeeId ? AGENT_MAPPINGS[l.employeeId] : null;
            return (
              <li key={i}>
                <span className="muted">{clock(l.at)}</span>
                {" "}
                {agent ? (
                  <span>
                    <strong>{agent.displayName} ({agent.agentType}): </strong>
                    {l.text}
                  </span>
                ) : (
                  <span className="muted">System: {l.text}</span>
                )}
              </li>
            );
          })}
        </ul>
      )}
    </section>
  );
}

