import { AGENT_MAPPINGS } from "../state/types";
import { useEffect, useRef, useState } from "react";
import type { ActionBody, Employee, EmployeeState, Task } from "../state/types";
import { DEMO_TEXT, cap, clock } from "./format";

const STATES: EmployeeState[] = ["idle", "working", "thinking", "waiting", "completed", "error"];

interface Props {
  employee: Employee;
  tasks: Task[];
  act: (a: ActionBody) => void;
  onClose: () => void;
  onOpenBoard: () => void;
}

export default function CharacterPanel({ employee, tasks, act, onClose, onOpenBoard }: Props) {
  const ref = useRef<HTMLElement>(null);
  const [pick, setPick] = useState("");
  const agent = AGENT_MAPPINGS[employee.id];

  useEffect(() => {
    const prev = document.activeElement as HTMLElement | null;
    ref.current?.focus();
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("keydown", onKey);
      prev?.focus?.();
    };
  }, []);

  const active = tasks.find((t) => t.id === employee.currentTaskId);
  const queue = tasks.filter((t) => t.assigneeId === employee.id && t.status === "todo");
  const assignable = tasks.filter((t) => t.status === "todo" && t.assigneeId !== employee.id);
  const busy = employee.currentTaskId !== null;

  return (
    <section
      className="panel"
      ref={ref}
      tabIndex={-1}
      aria-label={`${employee.role} details`}
    >
      <header>
        <h2>{employee.role}</h2>
        <p className="agent-type">{agent.agentType}</p>
        <button onClick={onClose} aria-label="Close panel">×</button>
      </header>
      <p className="badge">{DEMO_TEXT}</p>
      <p>
        State: <span className={`chip st-${employee.state}`}>{cap(employee.state)}</span>
      </p>
      <label>
        Set state{" "}
        <select
          value={employee.state}
          onChange={(e) => act({ type: "setState", employeeId: employee.id, state: e.target.value as EmployeeState })}
        >
          {STATES.map((s) => (
            <option key={s} value={s}>{cap(s)}</option>
          ))}
        </select>
      </label>

      <h3>Current task</h3>
      {active ? (
        <p>
          {active.title}{" "}
          <button onClick={() => act({ type: "completeTask", taskId: active.id })}>Complete</button>
        </p>
      ) : (
        <p className="muted">None</p>
      )}

      {queue.length > 0 && (
        <>
          <h3>Queue</h3>
          <ul className="rows">
            {queue.map((t) => (
              <li key={t.id}>
                {t.title}{" "}
                <button disabled={busy} onClick={() => act({ type: "startTask", taskId: t.id })}>Start</button>
              </li>
            ))}
          </ul>
        </>
      )}

      <h3>Assign a task</h3>
      {assignable.length === 0 ? (
        <p className="muted">
          No to-do tasks to assign. <button onClick={onOpenBoard}>Open task board</button>
        </p>
      ) : (
        <div className="row">
          <select value={pick} onChange={(e) => setPick(e.target.value)} aria-label="Task to assign">
            <option value="">Choose a task…</option>
            {assignable.map((t) => (
              <option key={t.id} value={t.id}>{t.title}</option>
            ))}
          </select>
          <button
            disabled={!pick}
            onClick={() => {
              act({ type: "assignTask", taskId: pick, assigneeId: employee.id });
              setPick("");
            }}
          >
            Assign
          </button>
        </div>
      )}

      <h3>Recent activity</h3>
      {employee.activity.length === 0 ? (
        <p className="muted">Nothing yet.</p>
      ) : (
        <ul className="rows log">
          {[...employee.activity].reverse().map((a, i) => (
            <li key={i}>
              <span className="muted">{clock(a.at)}</span> {a.text}
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

